import { assertSharedMutationAllowed, canDisplaySharedBoard, CLOSED_NIGHT_MESSAGE, isClosedNightFailure, isConnectivityFailure, isIdentityFailure, OFFLINE_MUTATION_MESSAGE, publishSharedConnectionState, SharedConnectionTracker, type SharedConnectionState } from './connection-safety'
